import{_ as a,c as i,o as t,ae as o}from"./chunks/framework.Dgg8-8ov.js";const m=JSON.parse('{"title":"Aalenian Utilities","description":"","frontmatter":{},"headers":[],"relativePath":"mods/utilities.md","filePath":"mods/utilities.md"}'),s={name:"mods/utilities.md"};function n(l,e,r,h,d,c){return t(),i("div",null,e[0]||(e[0]=[o(`<h1 id="aalenian-utilities" tabindex="-1">Aalenian Utilities <a class="header-anchor" href="#aalenian-utilities" aria-label="Permalink to &quot;Aalenian Utilities&quot;">​</a></h1><p><strong>Aalenian Utilities</strong> adds a number of server features, administrative tools, and chat commands to Path of Titans</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Run <code>/au</code> in-game for configuration and documentation! At least one Aalenian Controller creator mode object must exist on the server for every feature to work, so add one to your default creator mode save!</p><h2 id="chat-commands" tabindex="-1">Chat Commands <a class="header-anchor" href="#chat-commands" aria-label="Permalink to &quot;Chat Commands&quot;">​</a></h2><h3 id="commands" tabindex="-1">Commands: <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands:&quot;">​</a></h3><blockquote><p><code>/commands</code> (<code>/c</code>): lists commands available to everyone, that list changing to reflect which features you have enabled</p></blockquote><h3 id="optional-commands" tabindex="-1">Optional Commands: <a class="header-anchor" href="#optional-commands" aria-label="Permalink to &quot;Optional Commands:&quot;">​</a></h3><blockquote><p>/unstuck, /tp, /marks, /growth (/g), /zoom (/z), /moon, /baby, /leaderboard (/lb), /carryable, /give [Marks], /bank, /transfer [Username] [Marks], /fillnest, /poke, /shed</p></blockquote><h3 id="admin-rcon-commands-non-exhaustive-list" tabindex="-1">Admin/RCON Commands (Non-Exhaustive List): <a class="header-anchor" href="#admin-rcon-commands-non-exhaustive-list" aria-label="Permalink to &quot;Admin/RCON Commands (Non-Exhaustive List):&quot;">​</a></h3><blockquote><p>/kill [Username], /smite [Username], /execute [Username], /boss [Username], /freeze [Username], /restore [Username], /zoom [Username], /moon [Username], /zerogravity [Username], slow [Username], /drop [Username], /push [Username], /shield [Username], /listplayerpois, /light, /dark, /creator, /spectator</p></blockquote><h2 id="optional-tools" tabindex="-1">Optional Tools <a class="header-anchor" href="#optional-tools" aria-label="Permalink to &quot;Optional Tools&quot;">​</a></h2><h3 id="teleportation" tabindex="-1">Teleportation <a class="header-anchor" href="#teleportation" aria-label="Permalink to &quot;Teleportation&quot;">​</a></h3><ul><li>Configure <code>/tp</code> to use unlimited custom tp locations each with configurable costs and per-PLAYER cooldowns. Optional 30 second sleeping requirement therefor.</li><li>Solo-friendly waystones, or &quot;Advanced Waystones&quot; allow players to teleport from one waystone to another at a configurable cost. Implement an optional 30 second sleeping requirement.</li><li>Unlimited Teleport Stone placements. Players may teleport from one to another at a configurable cost, this system interfacing with Advanced Waystones. Implement an ptional 30 second sleeping requirement.</li><li>Temporary post-waystone and post-teleport immunity, with which players cannot deal or recieve damage for a configurable amount of seconds upon teleporting</li></ul><h3 id="spawning" tabindex="-1">Spawning <a class="header-anchor" href="#spawning" aria-label="Permalink to &quot;Spawning&quot;">​</a></h3><ul><li>Unlimited custom spawn locations</li><li>Temporary spawn immunity, with which players cannot deal or recieve damage for a configurable amount of seconds upon spawning</li></ul><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><ul><li>Configure <code>/marks</code> with a per-CHARACTER cooldown and customizable amount</li><li>Running <code>/leaderboard</code> (<code>/lb</code>) shows a leaderboard with the top 10 killers, bucket-kickers, and K/D ratios (as well as a player&#39;s own standing); leaderboard data is extractable with RCON</li><li>Death mesages</li><li>Join and leave messages</li><li>Instant shedding</li></ul><h2 id="creator-mode-objects" tabindex="-1">Creator Mode Objects <a class="header-anchor" href="#creator-mode-objects" aria-label="Permalink to &quot;Creator Mode Objects&quot;">​</a></h2><h3 id="power-stones" tabindex="-1">Power Stones <a class="header-anchor" href="#power-stones" aria-label="Permalink to &quot;Power Stones&quot;">​</a></h3><ul><li>Safe Zone Stone: players inside the effect radius cannot deal or recieve damage, while players in combat are unable to enter</li><li>Regeneration Stone: increases healing rate by a factor of 10</li><li>Moon Stone: gives players in the effect radius moon gravity</li><li>Teleport Stone <ul><li><em>only placeable from the configuration panel</em></li></ul></li><li>Placeable Waystone <ul><li><em>limit of 15 land and 5 underwater placements</em></li></ul></li></ul><h3 id="other-1" tabindex="-1">Other <a class="header-anchor" href="#other-1" aria-label="Permalink to &quot;Other&quot;">​</a></h3><ul><li>Aalenian Controller: one or more must exist on the server or not all features of htis mod will work properly</li><li>Safety Cone</li></ul><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>New webhooks are available for you to add to your server&#39;s Game.ini, see them just below!</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[ServerWebhooks]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PlayerVoiceCall</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PlayerChangeRestState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Add the following line of code to your server&#39;s GameUserSettings.ini</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[PathOfTitans.Mods]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EnabledMods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ModSku</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UGC_M_Y250GRMEVZ_SK&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BuildSku</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;release&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div>`,29)]))}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
